INSERT INTO criteria (id, code, version, name, description, check_templates, active) VALUES
(1, 'functional_correctness', 1, 'Реализация программной логики', 'Проверить наблюдаемые условия: Результат соответствует контракту на допустимых входных данных; Граничные допустимые входные данные дают ожидаемый результат', '["Результат соответствует контракту на допустимых входных данных","Граничные допустимые входные данные дают ожидаемый результат"]'::jsonb, TRUE),
(2, 'algorithm_correctness', 1, 'Алгоритмы и структуры данных', 'Проверить наблюдаемые условия: Результат совпадает с эталоном на контрольных наборах; Решение соблюдает заданные ограничения времени и памяти', '["Результат совпадает с эталоном на контрольных наборах","Решение соблюдает заданные ограничения времени и памяти"]'::jsonb, TRUE),
(3, 'change_contract', 1, 'Чтение и изменение чужого кода', 'Проверить наблюдаемые условия: Запрошенное изменение выполняет новый контракт; Оговорённые прежние сценарии продолжают работать', '["Запрошенное изменение выполняет новый контракт","Оговорённые прежние сценарии продолжают работать"]'::jsonb, TRUE),
(4, 'defect_resolution', 1, 'Поиск и исправление ошибок', 'Проверить наблюдаемые условия: Исходный дефект воспроизведён и его причина подтверждена; Исправление устраняет дефект без оговорённых регрессий', '["Исходный дефект воспроизведён и его причина подтверждена","Исправление устраняет дефект без оговорённых регрессий"]'::jsonb, TRUE),
(5, 'behavior_preservation', 1, 'Рефакторинг', 'Проверить наблюдаемые условия: Оговорённое внешнее поведение сохранено; Заявленное структурное изменение выполнено по конкретным ограничениям задания', '["Оговорённое внешнее поведение сохранено","Заявленное структурное изменение выполнено по конкретным ограничениям задания"]'::jsonb, TRUE),
(6, 'api_contract', 1, 'Проектирование и реализация API', 'Проверить наблюдаемые условия: Ответы соответствуют заданной структуре и кодам состояния; Ошибочные запросы обработаны согласно контракту', '["Ответы соответствуют заданной структуре и кодам состояния","Ошибочные запросы обработаны согласно контракту"]'::jsonb, TRUE),
(7, 'business_rules', 1, 'Моделирование бизнес-логики', 'Проверить наблюдаемые условия: Допустимые переходы состояния выполняют заданные правила; Запрещённые переходы не создают недопустимое состояние', '["Допустимые переходы состояния выполняют заданные правила","Запрещённые переходы не создают недопустимое состояние"]'::jsonb, TRUE),
(8, 'integration_contract', 1, 'Интеграция сервисов', 'Проверить наблюдаемые условия: Корректный обмен соответствует контракту внешней системы; Указанные сбои внешней системы обрабатываются по условию', '["Корректный обмен соответствует контракту внешней системы","Указанные сбои внешней системы обрабатываются по условию"]'::jsonb, TRUE),
(9, 'async_execution', 1, 'Асинхронная обработка', 'Проверить наблюдаемые условия: Фоновая задача выполняется и её результат доступен по условию; Указанные ошибки выполнения и повторная доставка обработаны по условию', '["Фоновая задача выполняется и её результат доступен по условию","Указанные ошибки выполнения и повторная доставка обработаны по условию"]'::jsonb, TRUE),
(10, 'access_enforcement', 1, 'Контроль доступа в приложении', 'Проверить наблюдаемые условия: Разрешённые действия доступны указанным ролям; Запрещённые действия и доступ к чужим данным блокируются', '["Разрешённые действия доступны указанным ролям","Запрещённые действия и доступ к чужим данным блокируются"]'::jsonb, TRUE),
(11, 'layout_conformance', 1, 'Создание интерфейса по макету', 'Проверить наблюдаемые условия: Разметка соответствует перечисленным параметрам макета и контрольным размерам экрана; Оговорённые состояния элементов отображаются корректно', '["Разметка соответствует перечисленным параметрам макета и контрольным размерам экрана","Оговорённые состояния элементов отображаются корректно"]'::jsonb, TRUE),
(12, 'state_transitions', 1, 'Управление состоянием приложения', 'Проверить наблюдаемые условия: Действия пользователя приводят к заданным состояниям; Повторные действия и указанные отмены не нарушают состояние', '["Действия пользователя приводят к заданным состояниям","Повторные действия и указанные отмены не нарушают состояние"]'::jsonb, TRUE),
(13, 'client_api_states', 1, 'Взаимодействие клиента с API', 'Проверить наблюдаемые условия: Загрузка и успешный ответ отображаются согласно условию; Ошибка, повтор и отмена обрабатываются по заданным правилам', '["Загрузка и успешный ответ отображаются согласно условию","Ошибка, повтор и отмена обрабатываются по заданным правилам"]'::jsonb, TRUE),
(14, 'accessibility_scenarios', 1, 'Доступность интерфейса', 'Проверить наблюдаемые условия: Заданный сценарий выполняется с клавиатуры с ожидаемым фокусом; Оговорённые элементы имеют требуемые доступные имена и состояния', '["Заданный сценарий выполняется с клавиатуры с ожидаемым фокусом","Оговорённые элементы имеют требуемые доступные имена и состояния"]'::jsonb, TRUE),
(15, 'platform_interaction', 1, 'Платформенные функции приложения', 'Проверить наблюдаемые условия: Функция устройства выполняет заданный сценарий; Отказ в разрешении и отсутствие возможности обработаны по условию', '["Функция устройства выполняет заданный сценарий","Отказ в разрешении и отсутствие возможности обработаны по условию"]'::jsonb, TRUE),
(16, 'data_operations', 1, 'Работа с запросами', 'Проверить наблюдаемые условия: Результат запросов и изменений совпадает с ожидаемыми данными; Пустые, повторяющиеся и предельные данные обработаны по заданному контракту', '["Результат запросов и изменений совпадает с ожидаемыми данными","Пустые, повторяющиеся и предельные данные обработаны по заданному контракту"]'::jsonb, TRUE),
(17, 'schema_constraints', 1, 'Моделирование структуры данных', 'Проверить наблюдаемые условия: Схема представляет все заданные сущности и связи; Оговорённые недопустимые состояния блокируются ограничениями', '["Схема представляет все заданные сущности и связи","Оговорённые недопустимые состояния блокируются ограничениями"]'::jsonb, TRUE),
(18, 'transaction_atomicity', 1, 'Транзакции и целостность', 'Проверить наблюдаемые условия: Успешная операция сохраняет требуемое согласованное состояние; При указанных сбоях отсутствуют запрещённые частичные изменения', '["Успешная операция сохраняет требуемое согласованное состояние","При указанных сбоях отсутствуют запрещённые частичные изменения"]'::jsonb, TRUE),
(19, 'query_efficiency', 1, 'Анализ производительности запросов', 'Проверить наблюдаемые условия: Измерение выполнено на заданных данных и по воспроизводимой процедуре; Изменение сохраняет результат и удовлетворяет заданному ограничению производительности', '["Измерение выполнено на заданных данных и по воспроизводимой процедуре","Изменение сохраняет результат и удовлетворяет заданному ограничению производительности"]'::jsonb, TRUE),
(20, 'database_restore', 1, 'Сохранность и восстановление БД', 'Проверить наблюдаемые условия: Контрольные данные восстанавливаются в указанную точку; Восстановленные данные проходят заданные проверки целостности', '["Контрольные данные восстанавливаются в указанную точку","Восстановленные данные проходят заданные проверки целостности"]'::jsonb, TRUE),
