(64, 'metric_alignment', 1, 'Определение продуктовых показателей', 'Проверить наблюдаемые условия: Метрики связаны с указанной целью и имеют определение расчёта; Оговорённые искажения и ограничения интерпретации объяснены', '["Метрики связаны с указанной целью и имеют определение расчёта","Оговорённые искажения и ограничения интерпретации объяснены"]'::jsonb, TRUE),
(65, 'decision_evidence', 1, 'Объяснение и защита решения', 'Проверить наблюдаемые условия: Объяснение согласуется с фактически выполненным решением; Ответы на заданные вопросы подтверждены примерами или расчётами', '["Объяснение согласуется с фактически выполненным решением","Ответы на заданные вопросы подтверждены примерами или расчётами"]'::jsonb, TRUE),
(66, 'input_validation', 1, 'Проверка входных данных', 'Проверить наблюдаемые условия: Входы с заданными нарушениями формата отклоняются; Недопустимый ввод не создаёт запрещённых изменений', '["Входы с заданными нарушениями формата отклоняются","Недопустимый ввод не создаёт запрещённых изменений"]'::jsonb, TRUE),
(67, 'sql_parameterization', 1, 'Параметризация запросов', 'Проверить наблюдаемые условия: Переданные значения не меняют структуру SQL-запроса; Контрольные значения обрабатываются как данные с ожидаемым результатом', '["Переданные значения не меняют структуру SQL-запроса","Контрольные значения обрабатываются как данные с ожидаемым результатом"]'::jsonb, TRUE),
(68, 'concurrency_consistency', 1, 'Согласованность конкурентных операций', 'Проверить наблюдаемые условия: Заданные параллельные операции сохраняют инварианты; Оговорённые конфликты обрабатываются без запрещённых результатов', '["Заданные параллельные операции сохраняют инварианты","Оговорённые конфликты обрабатываются без запрещённых результатов"]'::jsonb, TRUE),
(69, 'request_idempotency', 1, 'Повторное выполнение запроса', 'Проверить наблюдаемые условия: Повтор с тем же ключом не дублирует заданный эффект; Конфликтующее содержимое с тем же ключом обработано по контракту', '["Повтор с тем же ключом не дублирует заданный эффект","Конфликтующее содержимое с тем же ключом обработано по контракту"]'::jsonb, TRUE),
(70, 'container_configuration', 1, 'Конфигурация контейнера', 'Проверить наблюдаемые условия: Образ собирается и запускается в заданной среде; Параметры, ресурсы и доступы соответствуют ограничениям задания', '["Образ собирается и запускается в заданной среде","Параметры, ресурсы и доступы соответствуют ограничениям задания"]'::jsonb, TRUE),
(71, 'orchestration_recovery', 1, 'Восстановление в оркестраторе', 'Проверить наблюдаемые условия: Заданный отказ экземпляра приводит к предусмотренному восстановлению; Готовность, трафик и данные после восстановления соответствуют условию', '["Заданный отказ экземпляра приводит к предусмотренному восстановлению","Готовность, трафик и данные после восстановления соответствуют условию"]'::jsonb, TRUE),
(72, 'code_readability', 1, 'Прослеживаемость структуры кода', 'Проверить наблюдаемые условия: Указанные точки изменения локализуются по именам и структуре; Перечисленные ограничения структуры соблюдены без изменения поведения', '["Указанные точки изменения локализуются по именам и структуре","Перечисленные ограничения структуры соблюдены без изменения поведения"]'::jsonb, TRUE)
ON CONFLICT (code, version) DO NOTHING;

