JOIN criteria AS c ON c.code = v.criterion_code AND c.version = v.criterion_version
JOIN competencies AS p ON p.code = v.competency_code
ON CONFLICT (criterion_id, competency_id) DO NOTHING;
SELECT setval(pg_get_serial_sequence('mesto_assessment.specializations', 'id'), GREATEST(COALESCE(MAX(id), 1), 1), TRUE) FROM specializations;
SELECT setval(pg_get_serial_sequence('mesto_assessment.grades', 'id'), GREATEST(COALESCE(MAX(id), 1), 1), TRUE) FROM grades;
SELECT setval(pg_get_serial_sequence('mesto_assessment.competencies', 'id'), GREATEST(COALESCE(MAX(id), 1), 1), TRUE) FROM competencies;
SELECT setval(pg_get_serial_sequence('mesto_assessment.technologies', 'id'), GREATEST(COALESCE(MAX(id), 1), 1), TRUE) FROM technologies;
SELECT setval(pg_get_serial_sequence('mesto_assessment.criteria', 'id'), GREATEST(COALESCE(MAX(id), 1), 1), TRUE) FROM criteria;
COMMIT;
